const N = Math.round(p.puffs), H = api.h, W = api.w;
const src = W * 0.5, base = H - 1;
// dense column of rising puffs, overlapping near the chimney so it reads as one plume
const total = N * 2;
for (let i = 0; i < total; i++) {
  const ph = (api.t + i / total) % 1;
  const wob = api.rnd(i * 7 + 1) * 2 - 1;
  const y = base - ph * (H - 2);
  const climb = ph;
  const x = src + wob * p.drift * climb * climb * 0.9 + Math.sin(2 * Math.PI * (api.t + i * 0.37)) * p.drift * 0.4 * climb;
  // fat at the bottom too, so the puffs touch instead of beading
  const r = 1.1 + climb * p.girth * (0.65 + api.rnd(i * 13 + 5) * 0.5);
  const cut = p.fade;
  let a = climb < 0.06 ? climb / 0.06 : 1;
  if (climb > cut) a *= Math.max(0, 1 - (climb - cut) / (1 - cut));
  a *= p.intensity * 0.85;
  if (a <= 0.02) continue;
  const ci = climb < 0.22 ? 3 : climb < 0.5 ? 2 : climb < 0.75 ? 1 : 0;
  const cx = Math.round(x), cy = Math.round(y);
  api.blob(cx, cy, r, ci, a);
  // fill the gap toward the next puff below so the column is continuous low down
  if (climb < 0.55) {
    const gy = Math.round(y + (H - 2) / total * 0.5);
    api.blob(Math.round(x), gy, r * 0.8, ci, a * 0.8);
  }
  if (climb < 0.5 && r > 1.4) api.blob(cx, cy - 1, r * 0.55, ci - 1 < 0 ? 0 : ci - 1, a * 0.6);
  // break up as it climbs
  if (climb > 0.45) {
    const shred = 2 + Math.round(climb * 4);
    for (let k = 0; k < shred; k++) {
      const ang = 2 * Math.PI * (api.rnd(i * 31 + k * 3 + 2) + api.t);
      const rr = r * (0.85 + api.rnd(i * 17 + k * 5 + 3) * 0.9);
      const sx = Math.round(x + Math.cos(ang) * rr * 1.2);
      const sy = Math.round(y + Math.sin(ang) * rr * 0.7);
      api.px(sx, sy, k % 2 ? 0 : 1, a * (0.6 - climb * 0.35));
    }
  }
}
// a small solid root at the chimney mouth so the smoke has a source
for (let k = 0; k < 3; k++) {
  const ry = base - k;
  api.blob(src + (k === 2 ? (Math.sin(2 * Math.PI * api.t) > 0 ? 1 : 0) : 0), ry, 1.2 + k * 0.25, 3, p.intensity * (0.75 - k * 0.12));
}
// evaporating wisps at the very top, fading out into nothing
for (let k = 0; k < 9; k++) {
  const ph2 = (api.t * 0.7 + k / 9) % 1;
  const yy = Math.round(1 + ph2 * 7);
  const xx = Math.round(src + (api.rnd(k * 11 + 9) * 2 - 1) * p.drift * 1.4 + Math.sin(2 * Math.PI * (api.t + k * 0.21)) * 1.2);
  api.px(xx, yy, 0, (1 - ph2) * 0.26 * p.intensity);
  if (ph2 < 0.6) api.px(xx + (k % 2 ? 1 : -1), yy, 0, (1 - ph2) * 0.15 * p.intensity);
}
